'use strict';

// MODULES //

var inherit = require( '@stdlib/utils/inherit' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var Socket = require( './socket' ).base;
var log = require( './custom_log.js' );


// MAIN //

/**
* Shell socket constructor.
*
* @private
* @constructor
* @param {Kernel} kernel - jupyter kernel instance
* @param {Options} options - constructor options
* @param {string} options.ip - client address
* @param {number} options.shell_port - shell port
* @param {string} options.transport - protocol name
* @param {string} options.signature_scheme - signature scheme
* @param {string} options.key - signature key
* @returns {HBSocket} socket instance
*/
function HBSocket( kernel, options ) {
	if ( !( this instanceof HBSocket ) ) {
		return new HBSocket( kernel, options );
	}

	// Cache a reference to the kernel instance:
	this._kernel = kernel;

	// Call the parent constructor:
	Socket.call( this, 'rep', options.ip, options.hb_port, options.transport, options.signature_scheme, options.key );

	log( 'hb_socket.js: Constructing hb at port: ' + String( options.hb_port ) )

	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( HBSocket, Socket );

/**
* Initializes heartbeat loop.
*
* @private
* @name listen
* @memberof HBSocket.prototype
* @type {Function}
* @returns {void}
*/
setNonEnumerableReadOnly( HBSocket.prototype, 'listen', function listen() {
	var self = this;

	// Call the parent method:
	Socket.prototype.listen.call( this );

	this.on( 'message', onMessage );

	/**
	* Callback invoked upon receiving a zmq "message" event.
	*
	* @private
	* @param {Buffer} message - raw ping
	* @returns {void}
	*/
	function onMessage( message ) {
		self.send( message );
	}
});

// TODO: add methods for graceful closing.


// EXPORTS //

module.exports = HBSocket;
